package edu.synergy.algorithms.finalproject;
import java.util.*;
public final class StudentAlgorithms { private StudentAlgorithms(){} /** Time: O(n log n) average, O(n^2) worst. */ public static void quickSort(Student[]a){quick(a,0,a.length-1);} private static void quick(Student[]a,int lo,int hi){if(lo>=hi)return;int p=partition(a,lo,hi);quick(a,lo,p-1);quick(a,p+1,hi);} private static int partition(Student[]a,int lo,int hi){int pivot=a[hi].grade(),i=lo;for(int j=lo;j<hi;j++)if(a[j].grade()<=pivot){Student t=a[i];a[i++]=a[j];a[j]=t;}Student t=a[i];a[i]=a[hi];a[hi]=t;return i;} /** Time: O(log n). */ public static Student binarySearchGrade(Student[]a,int grade){int l=0,r=a.length-1;while(l<=r){int m=(l+r)>>>1;int g=a[m].grade();if(g==grade)return a[m];if(g<grade)l=m+1;else r=m-1;}return null;} /** Time: O(n log g) with TreeMap. */ public static Map<Integer,List<Student>> groupByGrade(Student[]a){Map<Integer,List<Student>>m=new TreeMap<>();for(Student s:a)m.computeIfAbsent(s.grade(),k->new ArrayList<>()).add(s);return m;} }
